'use client'
import React, { useEffect, useRef } from 'react'
import gsap from 'gsap'
import { BasePhaseProps } from '@/lib/types'
import { playMenuSelect } from '@/lib/sounds'

export default function WarningScreen({ onComplete, sounds }: BasePhaseProps) {
    const cardRef = useRef<HTMLDivElement | null>(null)
    const flashRef = useRef<HTMLDivElement | null>(null)

    useEffect(() => {
        let triggered = false

        if (cardRef.current) {
            gsap.fromTo(
                cardRef.current,
                { opacity: 0, scale: 0.96 },
                { opacity: 1, scale: 1, duration: 0.7, ease: 'power3.out' }
            )
        }

        const proceed = () => {
            if (triggered) return
            triggered = true

            playMenuSelect()

            try {
                if (sounds?.ambience) {
                    sounds.ambience.loop(true)
                    sounds.ambience.volume(0.35)
                    sounds.ambience.play()
                }
            } catch (e) {
                console.warn('Audio notice:', e)
            }

            if (flashRef.current) {
                gsap.to(flashRef.current, {
                    opacity: 1,
                    duration: 0.1,
                    ease: 'power2.in',
                    onComplete: () => {
                        if (flashRef.current) {
                            gsap.to(flashRef.current, {
                                opacity: 0,
                                duration: 0.25,
                                ease: 'power2.out',
                                onComplete,
                            })
                        } else {
                            onComplete()
                        }
                    },
                })
            } else {
                onComplete()
            }
        }

        const handleKey = (e: KeyboardEvent) => {
            if (e.key === 'Enter' || e.key === ' ' || e.key === 'Escape') {
                proceed()
            }
        }

        const handleClick = () => {
            proceed()
        }

        document.addEventListener('keydown', handleKey)
        document.addEventListener('click', handleClick)

        return () => {
            document.removeEventListener('keydown', handleKey)
            document.removeEventListener('click', handleClick)
            if (cardRef.current) gsap.killTweensOf(cardRef.current)
            if (flashRef.current) gsap.killTweensOf(flashRef.current)
        }
    }, [onComplete, sounds])

    return (
        <div
            style={{
                position: 'fixed',
                inset: 0,
                background: 'radial-gradient(ellipse at center, #0e0e14 0%, #050507 100%)',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                zIndex: 100,
                cursor: 'pointer',
                userSelect: 'none',
                padding: '24px',
            }}
        >
            <div className="heavy-vignette" />

            <div
                ref={cardRef}
                style={{
                    maxWidth: 740,
                    textAlign: 'center',
                    padding: '44px 36px',
                    zIndex: 110,
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    gap: '28px',
                    background: 'rgba(12, 12, 16, 0.92)',
                    backdropFilter: 'blur(16px)',
                    WebkitBackdropFilter: 'blur(16px)',
                    border: '1px solid rgba(255, 255, 255, 0.15)',
                    borderTop: '3px solid #f5a623',
                    boxShadow: '0 25px 70px rgba(0, 0, 0, 0.95), 0 0 30px rgba(245, 166, 35, 0.12)',
                }}
            >
                {/* Header Tag */}
                <div
                    style={{
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        fontSize: '0.85rem',
                        letterSpacing: '0.35em',
                        color: '#f5a623',
                        textTransform: 'uppercase',
                        fontWeight: 700,
                    }}
                >
                    BRIEFING // DEVELOPER PROFILE
                </div>

                {/* Natural, human-written text */}
                <p
                    style={{
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        fontSize: 'clamp(1rem, 2vw, 1.25rem)',
                        letterSpacing: '0.22em',
                        lineHeight: 1.7,
                        color: 'rgba(255, 255, 255, 0.85)',
                        textTransform: 'uppercase',
                        margin: 0,
                    }}
                >
                    WELCOME TO THE PORTFOLIO OF OM PANDEY.
                    <br />
                    INSPIRED BY GTA V, THIS EXPERIENCE SHOWCASES MY REAL PROJECTS,
                    <br />
                    ENGINEERING SKILLS, AND SYSTEM DESIGNS.
                </p>

                <div
                    style={{
                        width: '40px',
                        height: '2px',
                        background: 'rgba(255, 255, 255, 0.25)',
                    }}
                />

                <div className="smooth-pulse">
                    <span
                        style={{
                            fontFamily: 'ChaletLondon1960, "Bebas Neue", Montserrat, sans-serif',
                            fontSize: 'clamp(1.15rem, 2.6vw, 1.45rem)',
                            letterSpacing: '0.24em',
                            textTransform: 'uppercase',
                            color: '#ffffff',
                            background: 'rgba(255, 255, 255, 0.08)',
                            border: '1px solid rgba(255, 255, 255, 0.3)',
                            padding: '10px 24px',
                        }}
                    >
                        PRESS ENTER OR CLICK TO CONTINUE
                    </span>
                </div>
            </div>

            <div
                ref={flashRef}
                style={{
                    position: 'absolute',
                    inset: 0,
                    background: '#ffffff',
                    opacity: 0,
                    pointerEvents: 'none',
                    zIndex: 200,
                }}
            />
        </div>
    )
}
